// qa/households/lib/catalog.mjs -- the household types (archetypes) and the edge-case packs
// that are applied to each of them. generate.mjs turns archetypes x packs into one .md case
// per combination. Add a household type here, or a variation to a pack, and regenerate.
//
// Every archetype is a realistic base household on 2026-09-15. Every variation mutates a deep
// copy of it and says what the twist is and what to look at. Variations must not depend on
// the archetype's exact ids: use the ctx helpers (self, adults, firstIncome, firstExpense,
// nowAccount, liability, ...) which find the right pieces or add them when missing.

export const TODAY = "2026-09-15";
export const Y = 2026;
const iso = (y, m, d) => `${y}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
const bornAge = (age, m = 6, d = 1) => iso(Y - age - ((m > 9 || (m === 9 && d > 15)) ? 1 : 0), m, d);   // someone who is exactly `age` on TODAY (2026-09-15)

const person = (id, name, role, birthDate, extra = {}) => ({ id, name, role, birthDate, ...extra });
const acct = (id, name, type, balance, extra = {}) => ({ id, name, type, balance, asOf: TODAY, ownerId: "", institution: "", history: [], ...extra });
const inc = (id, name, type, amount, period, extra = {}) => ({ id, name, type, personId: "", amount, period, growth: 0, taxable: true, ...extra });
const exp = (id, name, category, amount, period, extra = {}) => ({ id, name, category, amount, period, inflates: true, ...extra });
const debt = (id, accountId, rate, minPayment, extra = {}) => ({ id, accountId, rate, minPayment, extra: 0, ...extra });
const goal = (id, name, icon, target, targetDate, extra = {}) => ({ id, name, icon, target, targetDate, priority: 2, saved: 0, fundedBy: [], monthly: 0, rate: null, inflates: false, ...extra });
const base = (household, rest) => ({ schemaVersion: 1, meta: { name: "Test plan", currency: "USD", locale: "en-US" }, household, accounts: [], income: [], expenses: [], debts: [], goals: [], assumptions: {}, netWorthHistory: [], ...rest });

