// ------------------------------------------------------------------------------------------
// ctx helpers: find the pieces a variation needs, or add them
// ------------------------------------------------------------------------------------------
export function ctxOf(plan) {
  const people = plan.household.people;
  const adults = people.filter((p) => p.role !== "dependent");
  const deps = people.filter((p) => p.role === "dependent");
  const self = people.find((p) => p.role === "self") ?? adults[0] ?? people[0];
  const firstActive = (arr) => arr.find((x) => !x.endDate && !x.startDate && x.period !== "once") ?? arr[0];
  const income = firstActive(plan.income) ?? null;
  const expense = firstActive(plan.expenses) ?? null;
  const essentialExpense = plan.expenses.find((x) => x.essential !== false && x.category === "housing") ?? expense;
  const nowAccount = plan.accounts.find((a) => a.type === "savings") ?? plan.accounts.find((a) => a.type === "checking") ?? null;
  const liability = plan.accounts.find((a) => a.type === "credit") ?? plan.accounts.find((a) => a.type === "loan") ?? plan.accounts.find((a) => ["mortgage", "student_loan", "other_liability"].includes(a.type)) ?? null;
  const goalItem = plan.goals[0] ?? null;
  return { people, adults, deps, self, income, expense, essentialExpense, nowAccount, liability, goalItem };
}
const ensureIncome = (plan) => { const c = ctxOf(plan); if (c.income) return c.income; const x = inc("i-added", `${c.self.name}'s pay`, "salary", 4000, "monthly", { personId: c.self.id }); plan.income.push(x); return x; };
const ensureExpense = (plan) => { const c = ctxOf(plan); if (c.expense) return c.expense; const x = exp("e-added", "Rent", "housing", 1500, "monthly"); plan.expenses.push(x); return x; };
const ensureNow = (plan) => { const c = ctxOf(plan); if (c.nowAccount) return c.nowAccount; const a = acct("a-added-sav", "Savings", "savings", 5000); plan.accounts.push(a); return a; };
const ensureLiability = (plan) => { const c = ctxOf(plan); if (c.liability) return c.liability; const a = acct("a-added-card", "Credit card", "credit", 3000); plan.accounts.push(a); plan.debts.push(debt("d-added-card", a.id, 0.22, 90)); return a; };
const detailOf = (plan, a) => plan.debts.find((d) => d.accountId === a.id);
const yearlyOf = (x) => (Number(x.amount) || 0) * ({ weekly: 52, biweekly: 26, semimonthly: 24, monthly: 12, quarterly: 4, annual: 1, once: 0 }[x.period] ?? 12);

// A variation: { slug, title, why, apply(plan) -> { twist, check: [..] } }
const V = (slug, title, why, apply) => ({ slug, title, why, apply });

